import re

for exp_id, exp in sorted(exps.items()):
    metrics = exp.get('metrics', {}) or {}
    spec = exp.get('spec', {}) or {}
    notes = exp.get('notes', '') or ''

    paths = set()

    # Check output_dir in spec
    od = spec.get('output_dir', '')
    if od:
        paths.add(od)

    # Check data_path in spec
    dp = spec.get('data_path', '')
    if dp:
        paths.add(dp)

