    def find_paths(obj):
        if isinstance(obj, str):
            # Look for file paths
            for match in re.findall(r'(?:/[\w\-.]+)+(?:\.\w+)?', obj):
                if len(match) > 10:
                    paths.add(match)
        elif isinstance(obj, dict):
            for v in obj.values():
                find_paths(v)
        elif isinstance(obj, list):
            for v in obj:
                find_paths(v)

    find_paths(metrics)

    # Check notes for paths
